const raw = $input.first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : {};

const cfg = {
  api_base: body.api_base || raw.api_base,
  start_mode: body.start_mode || raw.start_mode || 'existing',
  search_query: body.search_query ?? raw.search_query,
  search_cities: body.search_cities || raw.search_cities,
  search_max_pages: body.search_max_pages ?? raw.search_max_pages ?? 1,
  sites_limit: body.sites_limit ?? raw.sites_limit ?? 5,
  scrape_status: body.scrape_status || raw.scrape_status || 'pending',
  site_id: body.site_id || raw.site_id || '',
  offer_description: body.offer_description || raw.offer_description,
  sender_name: body.sender_name || raw.sender_name,
  sender_company: body.sender_company || raw.sender_company,
  sender_phone: body.sender_phone || raw.sender_phone,
  sender_email: body.sender_email || raw.sender_email,
  dry_run_submit: body.dry_run_submit ?? raw.dry_run_submit ?? true,
  headless: body.headless ?? raw.headless ?? true,
  skip_enrich_if_done: body.skip_enrich_if_done ?? raw.skip_enrich_if_done ?? true,
  auto_qualify: body.auto_qualify ?? raw.auto_qualify ?? true,
  skip_unqualified: body.skip_unqualified ?? raw.skip_unqualified ?? true,
  target_query: body.target_query || raw.target_query,
  target_description: body.target_description || raw.target_description,
  google_sheet_id: body.google_sheet_id || raw.google_sheet_id || '',
  google_sheet_name: body.google_sheet_name || raw.google_sheet_name || 'Results',
};

cfg.trigger_type = Object.keys(body).length ? 'webhook' : (raw.trigger_type || 'manual');

if (cfg.start_mode === 'single_site' && !cfg.site_id) {
  throw new Error('start_mode=single_site требует site_id (Config или webhook body)');
}

if (cfg.start_mode === 'full' && (!cfg.search_query || !cfg.search_cities?.length)) {
  throw new Error('start_mode=full требует search_query и search_cities');
}

return [{ json: cfg }];

const j = $input.first().json;

const pipelineBody = {
  offer_description: j.offer_description,
  sender_name: j.sender_name,
  sender_company: j.sender_company,
  sender_phone: j.sender_phone,
  sender_email: j.sender_email,
  dry_run_submit: j.dry_run_submit,
  headless: j.headless,
  skip_enrich_if_done: j.skip_enrich_if_done,
  auto_qualify: j.auto_qualify,
  skip_unqualified: j.skip_unqualified,
  target_query: j.target_query,
  target_description: j.target_description,
};

if (j.start_mode === 'single_site') {
  return [{
    json: {
      ...j,
      request_url: `${j.api_base}/pipeline/site/${j.site_id}`,
      request_body: pipelineBody,
    },
  }];
}

const batchBody = {
  ...pipelineBody,
  sites_limit: j.sites_limit,
  scrape_status: j.scrape_status,
};

if (j.start_mode === 'full') {
  batchBody.search_query = j.search_query;
  batchBody.search_cities = j.search_cities;
  batchBody.search_max_pages = j.search_max_pages;
}

return [{
  json: {
    ...j,
    request_url: `${j.api_base}/pipeline/batch`,
    request_body: batchBody,
  },
}];

const response = $('Run Pipeline').first().json;
const cfg = $('Prepare Run').first().json;
const timestamp = new Date().toISOString();

let sites = [];
if (Array.isArray(response)) {
  sites = response;
} else if (response && response.site_id) {
  sites = [response];
} else {
  throw new Error('Неожиданный ответ API: ' + JSON.stringify(response).slice(0, 500));
}

const stepStatus = (steps, name) => {
  const found = (steps || []).find((s) => s.step === name);
  return found ? found.status : '';
};

return sites.map((site) => {
  const steps = site.steps || [];
  const submitDetail = site.submit && typeof site.submit === 'object' ? site.submit : {};

  return {
    json: {
      run_at: timestamp,
      trigger: cfg.trigger_type,
      start_mode: cfg.start_mode,
      site_id: site.site_id,
      domain: site.domain,
      pipeline_status: site.status,
      enrich_status: stepStatus(steps, 'enrich'),
      forms_status: stepStatus(steps, 'forms'),
      outreach_status: stepStatus(steps, 'outreach'),
      submit_status: stepStatus(steps, 'submit'),
      outreach_id: site.outreach_id || '',
      submitted: submitDetail.submitted ?? false,
      dry_run: submitDetail.dry_run ?? true,
      fields_filled: submitDetail.fields_filled ?? 0,
      sent_status: '',
      message_subject: '',
      message_text: '',
      llm_fit_score: '',
      llm_is_fit: '',
      error_message: site.error_message || '',
    },
  };
});

const rows = $('Format Results').all();
const outreach = $('Fetch Outreach Details').first().json.items || [];
const bySite = Object.fromEntries(outreach.map((o) => [o.site_id, o]));

return rows.map((item) => {
  const o = bySite[item.json.site_id];
  if (o) {
    item.json.sent_status = o.sent_status || '';
    item.json.message_subject = o.message_subject || '';
    item.json.message_text = (o.message_text || '').slice(0, 1000);
    item.json.llm_fit_score = o.llm_fit_score ?? '';
    item.json.llm_is_fit = o.llm_is_fit ?? '';
  }
  return item;
});
